double ToArea(ReadOnlyParameter<Shape> s)
{
    switch (s.Kind)
    {
        case Shape::Kind_Circle: return ((3.0 * s.As_Circle.Radius) * s.As_Circle.Radius);
        case Shape::Kind_Rect: return (s.As_Rect.Width * s.As_Rect.Height);
        default: return 0.0;
    }
}

